{
  "case_id": "xsu_sg_006_work_history_information",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret nævner ikke, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen, og heller ikke at ansøgerens egne oplysninger om tidligere arbejdsforhold inddrages. Det nævner heller ikke, at tidligere arbejde før ansøgningen kan indgå, navnlig ved ophør af andre grunde uden forværring. Det tilføjer desuden ikke-understøttet indhold: reduceret fribeløb, studiejob i mindre omfang med skånehensyn, at jobbenes studierelevans og geografi ikke tillægges vægt, og at specialpædagogisk støtte og øget tidsforbrug ikke indgår. Svaret bygger på ældre afgørelser og ikke på den aktuelle vejledning. Det er en væsentlig juridisk mangel."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Af de fire kritiske elementer er kun arbejde under studiet delvist med, i form af arbejde ved siden af studiet. Skattestyrelsen som kilde, ansøgerens egne oplysninger om tidligere arbejdsforhold og arbejde før ansøgningen med forklaring om arbejdsophør og forværring mangler."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Spørgsmålet handler om, hvilke oplysninger Udbetaling Danmark bruger. Svaret går i stedet ind på ældre ankenævnsafgørelser og eksempler på beløb. Det undlader de centrale oplysningskilder og skriver selv, at kilderne ikke handler om Udbetaling Danmark. Det besvarer derfor ikke væsentlige dele af spørgsmålet."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til identificerbare kilder: konkrete afgørelser fra Ankenævnet med journalnumre og KEN-numre samt nummererede henvisninger."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "De angivne kilder er ældre afgørelser fra 2013-2015 og ikke den aktuelle vejledning (VEJ afsnit 3.4.1.3) eller de gældende bestemmelser i den frosne kildeafgrænsning. Svaret erkender selv, at de ikke handler direkte om Udbetaling Danmark. De er derfor ikke aktuelle eller anvendelige."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Den aktuelle officielle passage støtter ikke påstandene om reduceret fribeløb, studiejob med skånehensyn, studierelevans og geografi eller specialpædagogisk støtte. De ældre afgørelser kan ikke bruges til at støtte den aktuelle regel om Skattestyrelsen og tidligere arbejde. Påstandene er derfor ikke dækket af de gyldige kilder."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en række elementer uden støtte i det frosne materiale: fribeløbsgrænse som moment, vurdering af studiejob i mindre omfang med skånehensyn, udelukkelse af jobbets studierelevans og geografi samt at specialpædagogisk støtte og øget tidsforbrug ikke indgår."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Det påkrævede forbehold om, at tidligere arbejde særligt er relevant ved ophør af andre grunde uden forværring, og at oplysningerne indgår i en samlet vurdering og ikke alene afgør retten, er ikke bevaret. Svaret siger kun, at fribeløbet kan være et moment."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: det henviser til afgørelser og drager konklusioner om relevante momenter uden indre selvmodsigelser. Det peger selv på, at kilderne ikke direkte handler om Udbetaling Danmark."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret bruger overvejende varsomme formuleringer som 'kan være et moment', 'især' og 'typisk', og gør ikke skøn til absolutte regler. Ordet 'ikke' om det, der ikke indgår, er dog stærkt og ikke understøttet, men det ændrer ikke modaliteten i det centrale."
    }
  },
  "xhaile_coverage": {
    "A18": {
      "label": "no",
      "reason": "Svaret nævner ikke, at oplysninger om arbejdstimer og indkomst indhentes fra Skattestyrelsen. Det omtaler kun indkomst og arbejde generelt."
    },
    "A19": {
      "label": "no",
      "reason": "Svaret nævner ikke, at ansøgerens egne oplysninger om tidligere arbejdsforhold angives i ansøgningen og inddrages."
    },
    "A20": {
      "label": "partial",
      "reason": "Arbejde ved siden af studiet nævnes, og det svarer til arbejde under studiet. Arbejde før ansøgningen og betingelsen om ophør af andre årsager uden forværring nævnes ikke."
    }
  },
  "overall_notes": "Svaret er bygget på ældre afgørelser og ikke den aktuelle vejledning. Det mangler hovedelementerne (Skattestyrelsen, egne oplysninger, tidligere arbejde og ophørsårsag) og tilføjer ikke-understøttede momenter. Det er traceable, men ikke gyldigt eller understøttet."
}

